// WebAssembly parity harness.
//
// Loads the js/wasm build of the signing core and replays four committed
// corpora through it, asserting byte-identical output against how the native
// Go build responded:
//
//   - the golden vectors, whose recorded preimage, payload and final signed
//     entry are what the native build and @stellar/stellar-sdk already agree on;
//   - the differential fuzzing corpus, whose entries were generated by
//     cmd/difffuzz and whose payloads Go, JS and Python all reproduce;
//   - the differential regression cases frozen from past divergences;
//   - the fuzz seed corpus, replayed against testdata/wasm-parity/
//     fuzz_expectations.json, the native result cmd/gencorpus recorded for each
//     seed.
//
// The two-input DiffEntries fuzz target is the one corpus the harness does not
// replay: the wasm core decodes and hashes a single entry at a time and has no
// DiffEntries surface, so those seeds are listed in the expectations as
// non_replayed_targets and counted as skipped with that reason.
//
// The wasm build is a second compilation of the same Go code under a different
// toolchain and a different integer and memory model. The vectors and the
// differential corpus are cases someone generated once; the fuzz corpus is the
// same entries pushed through the entry decoder in a different build, so it is
// the closest thing to a differential test between the two compilations.
//
// The harness talks to the module exactly as a browser would: it passes base64
// XDR strings in and reads base64 XDR strings out. A source-account entry has
// no preimage (the transaction envelope covers it), so it is exercised through
// the pass-through path instead and reported as skipped, loudly, with the
// reason. A seed the native build refused must be refused by the wasm build
// too; that is asserted, not skipped.
//
// Usage: node wasm/parity.mjs [--wasm wasm/dist/soroauth.wasm]
//                            [--vectors testdata/vectors]
//                            [--differential DIR] (repeatable)
//                            [--fuzz testdata/fuzz]
//                            [--expectations testdata/wasm-parity/fuzz_expectations.json]
//                            [--budget-ms 60000]
// Exit status is 0 only when every case matched or was skipped with a reason,
// at least one case was checked, and the run stayed within its time budget.

import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");

// A fixed seed for the source-account pass-through probe. It is never used to
// sign anything -- the pass-through returns the entry before a signer is
// consulted -- it just has to be a valid 32-byte seed.
const PROBE_SEED = "00".repeat(32);

// DEFAULT_DIFFERENTIAL is the set of recorded corpora every run replays: the
// generated differential corpus, the regressions frozen from past differential
// divergences, and the regressions frozen from past wasm divergences. The last
// directory is empty until there is something to freeze, which is why a missing
// or empty directory is not an error.
const DEFAULT_DIFFERENTIAL = [
  join(ROOT, "testdata", "differential", "corpus"),
  join(ROOT, "testdata", "differential", "regressions"),
  join(ROOT, "testdata", "wasm-parity", "regressions"),
];

function parseArgs(argv) {
  let wasm = join(HERE, "dist", "soroauth.wasm");
  let vectors = join(ROOT, "testdata", "vectors");
  let fuzz = join(ROOT, "testdata", "fuzz");
  let expectations = join(ROOT, "testdata", "wasm-parity", "fuzz_expectations.json");
  let differential = [...DEFAULT_DIFFERENTIAL];
  let budgetMs = 60000;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--wasm") wasm = resolve(argv[++i]);
    else if (argv[i] === "--vectors") vectors = resolve(argv[++i]);
    else if (argv[i] === "--fuzz") fuzz = resolve(argv[++i]);
    else if (argv[i] === "--expectations") expectations = resolve(argv[++i]);
    else if (argv[i] === "--differential") differential.push(resolve(argv[++i]));
    else if (argv[i] === "--budget-ms") budgetMs = Number(argv[++i]);
    else if (argv[i] === "--no-default-differential") differential = [];
    else throw new Error(`unknown argument: ${argv[i]}`);
  }
  return { wasm, vectors, fuzz, expectations, differential, budgetMs };
}

// loadRuntime installs the globals wasm_exec.js expects and evaluates it,
// leaving globalThis.Go defined. The shim is copied next to the wasm by
// wasm/build.sh so the two always match.
async function loadRuntime(wasmPath) {
  const require = createRequire(import.meta.url);
  globalThis.require = require;
  globalThis.fs = require("node:fs");
  globalThis.path = require("node:path");

  const shim = join(dirname(wasmPath), "wasm_exec.js");
  let source;
  try {
    source = readFileSync(shim, "utf8");
  } catch {
    throw new Error(
      `missing ${shim}; run wasm/build.sh to produce the module and its runtime shim`,
    );
  }
  // The shim is a plain IIFE that defines globalThis.Go; evaluating it as a
  // script (not as a module) matches how a browser script tag would load it.
  (0, eval)(source);

  const go = new globalThis.Go();
  go.argv = ["soroauth.wasm"];
  go.env = {};

  const bytes = readFileSync(wasmPath);
  const { instance } = await WebAssembly.instantiate(bytes, go.importObject);

  // The Go program blocks in select{} after it installs its bindings, so this
  // promise never settles. Do not await it.
  go.run(instance);

  // Wait for main to install the bindings. Bounded so a broken module fails
  // loudly instead of hanging the job.
  for (let i = 0; i < 1000; i++) {
    if (globalThis.soroauth) return globalThis.soroauth;
    await new Promise((r) => setTimeout(r, 10));
  }
  throw new Error("timed out waiting for globalThis.soroauth from the wasm module");
}

function sha256Hex(label) {
  return createHash("sha256").update(label).digest("hex");
}

// call invokes a binding and throws on a {ok:false} envelope, the same way the
// TypeScript wrapper does.
function call(api, name, ...args) {
  const fn = api[name];
  if (typeof fn !== "function") throw new Error(`module does not export ${name}`);
  const result = fn(...args);
  if (!result || result.ok !== true) {
    throw new Error(`${name}: ${(result && result.error) || "unknown error"}`);
  }
  return result;
}

function loadVectors(dir) {
  const names = readdirSync(dir)
    .filter((n) => n.endsWith(".json"))
    .sort();
  if (names.length === 0) throw new Error(`no vectors found in ${dir}`);
  return names.map((n) => JSON.parse(readFileSync(join(dir, n), "utf8")));
}

// loadJSONDir reads every .json file in dir, sorted by name. A missing or empty
// directory yields [], which is how an empty regressions/ directory stays legal.
function loadJSONDir(dir) {
  if (!existsSync(dir)) return [];
  const names = readdirSync(dir)
    .filter((n) => n.endsWith(".json"))
    .sort();
  return names.map((n) => ({ file: join(dir, n), json: JSON.parse(readFileSync(join(dir, n), "utf8")) }));
}

// readSeedArgs parses every []byte literal out of a Go fuzz corpus file, the
// values cmd/gencorpus wrote: one per argument of the target's fuzz function.
// A single-input target has one; the two-input DiffEntries target has two.
// Anything that is not a []byte literal is an error rather than a silent skip.
function readSeedArgs(path) {
  const lines = readFileSync(path, "utf8").split("\n");
  if (lines[0] !== "go test fuzz v1") {
    throw new Error(`not a Go fuzz corpus file (missing "go test fuzz v1" header): ${path}`);
  }
  const prefix = "[]byte(";
  const args = [];
  for (const raw of lines.slice(1)) {
    const literal = raw.trim();
    if (literal === "") continue;
    if (!literal.startsWith(prefix) || !literal.endsWith(")")) {
      throw new Error(`unsupported argument literal in ${path}: ${literal}`);
    }
    const quoted = literal.slice(prefix.length, -1);
    if (!quoted.startsWith('"') || !quoted.endsWith('"')) {
      throw new Error(`unsupported argument literal in ${path}: ${literal}`);
    }
    // The literal body is a Go string (strconv.Quote output); goUnquote
    // recovers the exact bytes it encodes.
    args.push(goUnquote(quoted.slice(1, -1)));
  }
  if (args.length === 0) {
    throw new Error(`no []byte argument in ${path}`);
  }
  return args;
}

// goUnquote decodes the body of a Go double-quoted string literal. Go's \xNN
// (a raw byte), \uNNNN and \UNNNNNNNN forms are not JSON, so this decodes them
// directly. A literal rune is re-encoded to its UTF-8 bytes, which is what
// strconv.Quote wrote for printable characters.
function goUnquote(inner) {
  const bytes = [];
  const chars = [...inner];
  for (let i = 0; i < chars.length; i++) {
    const c = chars[i];
    if (c !== "\\") {
      bytes.push(...Buffer.from(c, "utf8"));
      continue;
    }
    const next = chars[++i];
    switch (next) {
      case "a": bytes.push(0x07); break;
      case "b": bytes.push(0x08); break;
      case "f": bytes.push(0x0c); break;
      case "n": bytes.push(0x0a); break;
      case "r": bytes.push(0x0d); break;
      case "t": bytes.push(0x09); break;
      case "v": bytes.push(0x0b); break;
      case "\\": bytes.push(0x5c); break;
      case '"': bytes.push(0x22); break;
      case "'": bytes.push(0x27); break;
      case "x": {
        bytes.push(parseInt(chars.slice(i + 1, i + 3).join(""), 16));
        i += 2;
        break;
      }
      case "u": {
        const cp = parseInt(chars.slice(i + 1, i + 5).join(""), 16);
        bytes.push(...Buffer.from(String.fromCodePoint(cp), "utf8"));
        i += 4;
        break;
      }
      case "U": {
        const cp = parseInt(chars.slice(i + 1, i + 9).join(""), 16);
        bytes.push(...Buffer.from(String.fromCodePoint(cp), "utf8"));
        i += 8;
        break;
      }
      default:
        throw new Error(`unsupported escape \\${next}`);
    }
  }
  return Buffer.from(bytes);
}

function vectorsMatch(api, vector) {
  // A source-account entry has no preimage. Exercise the pass-through instead:
  // authorizeWithSeed must hand the entry back byte-identical.
  let preimage;
  try {
    preimage = call(api, "preimage", vector.unsigned_entry_xdr, vector.valid_until_ledger, vector.network_passphrase);
  } catch (err) {
    if (!/source.account/i.test(err.message)) throw err;
    const passed = call(
      api, "authorizeWithSeed",
      vector.unsigned_entry_xdr, vector.valid_until_ledger,
      vector.network_passphrase, PROBE_SEED, "",
    ).entryB64;
    if (passed !== vector.unsigned_entry_xdr) {
      return { status: "mismatch", detail: "source-account pass-through changed the entry" };
    }
    return {
      status: "skip",
      detail: `no preimage: credential_type=source_account (pass-through verified): ${err.message}`,
    };
  }

  if (preimage.preimageXdr !== vector.preimage_xdr) {
    return { status: "mismatch", detail: "preimage differs" };
  }
  if (preimage.payloadHex !== vector.payload_hex) {
    return { status: "mismatch", detail: "payload differs" };
  }

  // The standalone payload entry point must agree with the one computed from
  // the entry; a remote signer that only receives the preimage depends on it.
  const standalone = call(api, "payload", preimage.preimageXdr).payloadHex;
  if (standalone !== vector.payload_hex) {
    return { status: "mismatch", detail: "payload(preimage) differs from recorded payload" };
  }

  // A classic-account multisig step assembles several signatures over the same
  // payload. The wasm binding signs with a single seed (authorizeWithSeed), so
  // it cannot build that entry; the preimage, payload and standalone-payload
  // checks above still ran. Report it as a skip with the reason rather than
  // silently comparing a single-signer entry and calling it a match.
  if (vector.steps.some((step) => step.multisig)) {
    return {
      status: "skip",
      detail:
        "multisig signed entry: the wasm binding exposes single-seed signing " +
        "only (preimage and payload matched)",
    };
  }

  // Replay every signing step, exactly as golden_test.go does.
  let current = vector.unsigned_entry_xdr;
  for (const step of vector.steps) {
    current = call(
      api, "authorizeWithSeed",
      current, vector.valid_until_ledger, vector.network_passphrase,
      sha256Hex(step.signer_label), step.for_address ?? "",
    ).entryB64;
  }
  if (current !== vector.signed_entry_xdr) {
    return { status: "mismatch", detail: "signed entry differs" };
  }

  return { status: "match", detail: "" };
}

// differentialMatch replays one differential case. The case carries the bytes
// cmd/difffuzz recorded from the native build, so this is a byte-for-byte
// comparison with no second decode in the harness to drift.
function differentialMatch(api, c) {
  if (!c.preimage_xdr) {
    return {
      status: "skip",
      detail: `no preimage: credential_arm=${c.credential_arm} (the transaction envelope authenticates it)`,
    };
  }
  const preimage = call(api, "preimage", c.unsigned_entry_xdr, c.valid_until_ledger, c.network_passphrase);
  if (preimage.preimageXdr !== c.preimage_xdr) {
    return { status: "mismatch", detail: "preimage differs" };
  }
  if (preimage.payloadHex !== c.payload_hex) {
    return { status: "mismatch", detail: "payload differs" };
  }
  const standalone = call(api, "payload", preimage.preimageXdr).payloadHex;
  if (standalone !== c.payload_hex) {
    return { status: "mismatch", detail: "payload(preimage) differs from recorded payload" };
  }
  return { status: "match", detail: "" };
}

// fuzzMatch replays one seed against its recorded native expectation. A seed
// the native build refused must be refused here (a rejection is a match, not a
// skip); a seed it accepted must produce the recorded bytes.
function fuzzMatch(api, exp, dataB64) {
  const expectReject = exp.status === "reject";
  try {
    if (exp.operation === "payload") {
      const out = call(api, "payload", dataB64);
      if (expectReject) {
        return { status: "mismatch", detail: "wasm accepted a payload the native build refused" };
      }
      if (out.payloadHex !== exp.payload_hex) {
        return { status: "mismatch", detail: "payload differs" };
      }
      return { status: "match", detail: "" };
    }

    const preimage = call(api, "preimage", dataB64, exp.ledger, exp.passphrase);
    if (expectReject) {
      return { status: "mismatch", detail: "wasm accepted an entry the native build refused" };
    }
    if (preimage.preimageXdr !== exp.preimage_xdr) {
      return { status: "mismatch", detail: "preimage differs" };
    }
    if (preimage.payloadHex !== exp.payload_hex) {
      return { status: "mismatch", detail: "payload differs" };
    }
    const standalone = call(api, "payload", preimage.preimageXdr).payloadHex;
    if (standalone !== exp.payload_hex) {
      return { status: "mismatch", detail: "payload(preimage) differs from recorded payload" };
    }
    return { status: "match", detail: "" };
  } catch (err) {
    if (expectReject) return { status: "match", detail: "" };
    return { status: "mismatch", detail: `wasm refused a case the native build accepted: ${err.message}` };
  }
}

// fuzzCases pairs every replayed seed on disk with its recorded expectation. A
// replayed seed with no expectation is an error, not a skip: that would be a
// case the harness silently stopped checking. A seed directory named in
// non_replayed_targets is the exception: its seeds carry more than one entry,
// and the wasm core exposes no surface to replay a pair through, so they are
// counted as skipped with that reason rather than quietly dropped. A
// single-input directory the expectations do not describe is still an error, so
// adding a target cannot silently shrink the replay.
function fuzzCases(fuzzDir, expectations) {
  const { cases } = expectations;
  const nonReplayed = new Set(expectations.non_replayed_targets ?? []);
  const out = [];
  const skipped = [];
  for (const target of readdirSync(fuzzDir, { withFileTypes: true })) {
    if (!target.isDirectory() || target.name.startsWith(".")) continue;
    const dir = join(fuzzDir, target.name);
    const declaredNonReplayed = nonReplayed.has(target.name);
    for (const seed of readdirSync(dir).sort()) {
      const key = `${target.name}/${seed}`;
      const args = readSeedArgs(join(dir, seed));
      if (declaredNonReplayed) {
        skipped.push(key);
        continue;
      }
      if (args.length !== 1) {
        throw new Error(
          `${key} carries ${args.length} arguments; the wasm binding replays single-input seeds only, ` +
            `so ${target.name} must be listed in non_replayed_targets by cmd/gencorpus`,
        );
      }
      const exp = cases[key];
      if (!exp) throw new Error(`no native expectation recorded for ${key}; run cmd/gencorpus`);
      out.push({ key, exp, dataB64: args[0].toString("base64") });
    }
  }
  return { cases: out, skipped };
}

async function main() {
  const started = Date.now();
  const { wasm, vectors, fuzz, expectations: expectationsPath, differential, budgetMs } = parseArgs(process.argv.slice(2));

  // Load every corpus before touching the module, so a missing or empty
  // directory is visible in the header instead of silently dropping cases.
  const vectorCases = loadVectors(vectors);
  const differentialByDir = differential.map((dir) => ({ dir, cases: loadJSONDir(dir) }));
  const differentialCases = differentialByDir.flatMap((d) => d.cases);
  const expectations = JSON.parse(readFileSync(expectationsPath, "utf8"));
  const { cases: seeds, skipped: skippedSeeds } = fuzzCases(fuzz, expectations);

  console.log("WebAssembly parity harness");
  console.log(`wasm:         ${wasm}`);
  console.log(`vectors:      ${vectors} (${vectorCases.length})`);
  for (const { dir, cases } of differentialByDir) {
    console.log(`differential: ${dir} (${cases.length})`);
  }
  console.log(`fuzz:         ${fuzz} + ${expectationsPath} (${seeds.length})`);
  if (skippedSeeds.length > 0) {
    console.log(
      `fuzz skipped: ${skippedSeeds.length} pair seeds the single-input wasm binding cannot replay ` +
        `(${[...new Set(skippedSeeds.map((k) => k.split("/")[0]))].join(", ")})`,
    );
  }
  console.log(`budget:       ${budgetMs} ms`);

  const api = await loadRuntime(wasm);

  const counts = {
    vectors: { match: 0, skip: 0, mismatch: 0 },
    differential: { match: 0, skip: 0, mismatch: 0 },
    fuzz: { match: 0, skip: 0, mismatch: 0 },
  };
  let mismatched = 0;

  const report = (suite, name, result, loudOnMatch) => {
    if (result.status === "match") {
      counts[suite].match++;
      if (loudOnMatch) console.log(`  ok    ${name}`);
    } else if (result.status === "mismatch") {
      counts[suite].mismatch++;
      mismatched++;
      console.error(`  FAIL  ${name}: ${result.detail}`);
    } else {
      counts[suite].skip++;
      console.error(`  skip  ${name}: ${result.detail}`);
    }
  };

  for (const v of vectorCases) report("vectors", v.name, vectorsMatch(api, v), true);
  for (const { file, json } of differentialCases) {
    const name = `${json.name ?? file} (${file})`;
    report("differential", name, differentialMatch(api, json), false);
  }
  for (const { key, exp, dataB64 } of seeds) {
    const withContext = { ...exp, ledger: expectations.valid_until_ledger, passphrase: expectations.network_passphrase };
    report("fuzz", key, fuzzMatch(api, withContext, dataB64), false);
  }

  const total = vectorCases.length + differentialCases.length + seeds.length;
  console.log(
    `\nWebAssembly parity: ` +
      `${counts.vectors.match} vectors, ${counts.differential.match} differential, ${counts.fuzz.match} fuzz matched; ` +
      `${counts.vectors.skip + counts.differential.skip + counts.fuzz.skip} skipped; ` +
      `${mismatched} mismatched (of ${total} cases)`,
  );

  const elapsed = Date.now() - started;
  console.log(`elapsed: ${elapsed} ms (budget ${budgetMs} ms)`);

  if (mismatched > 0) {
    console.error(
      "\nThe wasm build does not reproduce the native corpora. Do not edit a case or a vector; fix the module. " +
        "Freeze a divergence by copying the case into testdata/wasm-parity/regressions/ (differential schema) and committing it.",
    );
    return 1;
  }
  if (counts.vectors.match + counts.differential.match + counts.fuzz.match === 0) {
    console.error("nothing was actually checked; refusing to report success");
    return 1;
  }
  if (elapsed > budgetMs) {
    console.error(`\nreplay took ${elapsed} ms, over the ${budgetMs} ms budget`);
    return 1;
  }
  return 0;
}

main()
  .then((code) => process.exit(code))
  .catch((err) => {
    console.error(err);
    process.exit(1);
  });
